package com.example.discovery.consumer.service;import com.example.discovery.consumer.model.ServiceInstance;import java.util.*;import java.util.concurrent.ConcurrentHashMap;import java.util.concurrent.atomic.AtomicInteger;import org.springframework.stereotype.Component;@Component public class RoundRobinLoadBalancer{private final Map<String,AtomicInteger> counters=new ConcurrentHashMap<>(); public List<ServiceInstance> orderedCandidates(String serviceName,List<ServiceInstance> instances){if(instances.isEmpty())return List.of();int start=Math.floorMod(counters.computeIfAbsent(serviceName,k->new AtomicInteger()).getAndIncrement(),instances.size());List<ServiceInstance> ordered=new ArrayList<>(instances.size());for(int i=0;i<instances.size();i++)ordered.add(instances.get((start+i)%instances.size()));return ordered;}}
